const ids = new Set();
for (const it of $input.all()) {
  if (it.json.alert_id) ids.add(it.json.alert_id);
  for (const r of it.json.results || []) if (r.meta && r.meta.alert_id) ids.add(r.meta.alert_id);
}
return [...ids].map((id) => ({ json: { alert_id: id } }));

